  return <ScreenState state={state}><div className="admin-screen"><PageLead title="Content & configuration" description="Operational settings are versioned changes, not ordinary interface preferences." /><AdminNotice tone="danger" title="Production safeguards required">The backend must re-check permissions, expected version, environment, and reason before applying any configuration mutation.</AdminNotice><AdminCard><AdminTabs active={tab} items={["Feature flags", "Policy values", "Help content"]} onChange={setTab} />{tab === "Feature flags" && <AdminTable columns={[{ key: "flag", label: "Flag", render: (row) => <span><strong>{row.key}</strong><small className="admin-cell-detail">{row.description}</small></span> }, { key: "env", label: "Environment", render: (row) => <AdminStatus status={row.environment} /> }, { key: "status", label: "State", render: (row) => <AdminStatus status={row.enabled ? "Enabled" : "Disabled"} /> }, { key: "updated", label: "Last change", render: (row) => `${row.updatedAt} by ${row.updatedBy}` }, { key: "action", label: "Action", render: (row) => permitted(session, "configuration:manage") ? <button className="admin-text-button" onClick={() => setAction({ title: `${row.enabled ? "Disable" : "Enable"} feature flag?`, target: `${row.key} · ${row.environment}`, description: "This may change behaviour for active users. A fresh expectedVersion is required in production.", confirmLabel: row.enabled ? "Disable flag" : "Enable flag", danger: row.environment === "production", run: (reason) => platformAdminService.updateFeatureFlag(row.key, !row.enabled, reason) })}>{row.enabled ? "Disable" : "Enable"}</button> : "Review only" }]} getRowKey={(row) => row.key} rows={platformAdminService.listFeatureFlags()} />}{tab === "Policy values" && <AdminTable columns={[{ key: "policy", label: "Policy", render: (row) => <strong>{row.label}</strong> }, { key: "key", label: "Key", render: (row) => row.key }, { key: "value", label: "Current value", render: (row) => row.value }, { key: "editable", label: "Control", render: (row) => row.editable && permitted(session, "configuration:manage") ? <button className="admin-text-button" onClick={() => setAction({ title: "Confirm policy value?", target: row.label, description: `This demo retains the current value (${row.value}). Production must submit a validated replacement value and expected version.`, confirmLabel: "Record change", danger: true, run: (reason) => platformAdminService.updatePolicy(row.key, row.value, reason) })}>Edit value</button> : "Locked" }]} getRowKey={(row) => row.key} rows={platformAdminService.listPolicies()} />}{tab === "Help content" && <div className="admin-placeholder"><FileText /><h3>Help centre content workspace</h3><p>Backend-managed articles, publish state, revision history, preview, and rollback belong here. The editor remains blocked until the content API is available.</p></div>}</AdminCard><ActionLayer action={action} onClose={() => setAction(null)} onComplete={(result) => setToast(result.message)} />{toast && <AdminToast message={toast} onDismiss={() => setToast("")} />}</div></ScreenState>;
