function Audit({ state, session }: ScreenProps) {
  const [risk, setRisk] = useState("");
  const [search, setSearch] = useState("");
  const [expanded, setExpanded] = useState<string | null>(null);
  const [toast, setToast] = useState("");
  const rows = platformAdminService.listAuditEvents().filter((row) => (!risk || row.risk === risk) && `${row.actor} ${row.action} ${row.target}`.toLowerCase().includes(search.toLowerCase()));
  return <ScreenState state={state}><div className="admin-screen"><PageLead title="Immutable audit log" description="Who did what, when, to which resource, and why—without storing unnecessary secrets." actions={permitted(session, "audit:export") && <AdminButton onClick={() => setToast("Audit export is available to the owner role, but the signed download API is not connected.")} tone="secondary"><Download /> Export audit log</AdminButton>} /><AdminCard><AdminToolbar search={search} onSearch={setSearch}><AdminSelect label="Risk" onChange={setRisk} options={["High", "Medium", "Low"]} value={risk} /></AdminToolbar><div className="admin-audit-list">{rows.length === 0 && <div className="admin-table-empty"><Search /><strong>No matching events</strong><span>Try a different search or risk filter.</span></div>}{rows.map((event) => <article key={event.id}><button aria-expanded={expanded === event.id} onClick={() => setExpanded(expanded === event.id ? null : event.id)}><span className={`admin-activity-icon is-${event.risk.toLowerCase()}`}><ShieldCheck /></span><span><strong>{event.action}</strong><small>{event.actor} · {event.role}</small></span><span>{event.target}<small>{event.createdAt}</small></span><AdminStatus status={event.risk} /><ArrowRight className={expanded === event.id ? "is-open" : ""} /></button>{expanded === event.id && <m.div className="admin-audit-detail" initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }}><FactGrid facts={[["Before", event.before ?? "Not captured"], ["After", event.after ?? "Not captured"], ["Reason", event.reason ?? "No reason supplied for this low-risk action"], ["Event ID", event.id]]} /></m.div>}</article>)}</div></AdminCard>{toast && <AdminToast message={toast} onDismiss={() => setToast("")} />}</div></ScreenState>;
}

function SystemOperations({ state, session }: ScreenProps) {
  const [action, setAction] = useState<PendingAction | null>(null);
  const [toast, setToast] = useState("");
  return <ScreenState state={state}><div className="admin-screen"><PageLead title="System operations" description="Safe observability for the services defined by the Oreno engineering architecture." actions={<span className="admin-live"><i /> Production view</span>} /><section className="admin-service-grid">{platformAdminService.listServiceHealth().map((service) => <article key={service.id}><span className={`admin-service-icon is-${service.status.toLowerCase()}`}><Activity /></span><div><strong>{service.name}</strong><small>{service.type}</small></div><AdminStatus status={service.status} /><dl><div><dt>Uptime</dt><dd>{service.uptime}</dd></div><div><dt>Latency</dt><dd>{service.latency ?? "n/a"}</dd></div><div><dt>Throughput</dt><dd>{service.throughput}</dd></div></dl></article>)}</section><AdminCard title="Failed background jobs" description="Payloads are deliberately summarised to avoid leaking secrets or personal data."><AdminTable columns={[{ key: "queue", label: "Queue", render: (row) => <strong>{row.queue}</strong> }, { key: "payload", label: "Safe summary", render: (row) => row.payloadSummary }, { key: "failed", label: "Failed", render: (row) => row.failedAt }, { key: "attempts", label: "Attempts", render: (row) => row.attempts }, { key: "error", label: "Error", render: (row) => row.error }, { key: "retry", label: "Action", render: (row) => permitted(session, "system:retry") ? <button className="admin-text-button" onClick={() => setAction({ title: "Retry this failed job?", target: `${row.queue} · ${row.id}`, description: "A new job attempt will be queued. The original failure remains in operational history.", confirmLabel: "Queue retry", danger: row.attempts >= 3, run: (reason) => platformAdminService.retryFailedJob(row.id, reason) })}><RefreshCw /> Retry</button> : "Review only" }]} getRowKey={(row) => row.id} rows={platformAdminService.listFailedJobs()} /></AdminCard><ActionLayer action={action} onClose={() => setAction(null)} onComplete={(result) => setToast(result.message)} />{toast && <AdminToast message={toast} onDismiss={() => setToast("")} />}</div></ScreenState>;
}

function Account({ state, session, roleSlug }: ScreenProps) {
  const [toast, setToast] = useState("");
  return <ScreenState state={state}><div className="admin-screen"><PageLead title="Admin account" description="Personal platform identity, role assignment, and security posture." actions={<Link className="admin-button admin-button--secondary admin-button--normal" href={`/platform-admin/login${roleSlug ? `?role=${roleSlug}` : ""}`}>Sign out demo</Link>} /><div className="admin-detail-grid"><AdminCard title="Administrator identity"><div className="admin-account-hero"><span>{session.initials}</span><div><h3>{session.name}</h3><p>{session.email}</p><AdminStatus status={session.role} /></div></div><FactGrid facts={[["Session expires", session.expiresAt], ["Two-factor", session.twoFactorSatisfied ? "Verified" : "Required"], ["Permissions", `${session.permissions.length} effective permissions`]]} /></AdminCard><AdminCard title="Security"><ul className="admin-security-list"><li><LockKeyhole /><span><strong>Two-factor authentication</strong><small>Authenticator app verified for this session</small></span><AdminStatus status="Enabled" /></li><li><KeyRound /><span><strong>Recovery codes</strong><small>Rotate after using any recovery code</small></span><AdminButton onClick={() => setToast("Recovery codes were not changed; connect the authenticated rotation endpoint.")} size="small" tone="secondary">Rotate</AdminButton></li><li><ShieldCheck /><span><strong>Active sessions</strong><small>This browser · last active now</small></span><AdminButton onClick={() => setToast("Other-session revocation is staged only; no live session was changed.")} size="small" tone="danger">Revoke others</AdminButton></li></ul></AdminCard><AdminCard className="admin-card--wide" title="Demo role preview" description="Use these links to verify navigation and action guards for each platform role."><div className="admin-role-links">{[["owner", "Platform Owner"], ["operations", "Operations Admin"], ["reviewer", "Talent Reviewer"], ["support", "Support Agent"], ["finance", "Finance Admin"], ["analyst", "Read-only Analyst"]].map(([slug, label]) => <Link className={session.role === label ? "is-active" : ""} href={`/platform-admin?role=${slug}`} key={slug}>{label}<ArrowRight /></Link>)}</div></AdminCard></div>{toast && <AdminToast message={toast} onDismiss={() => setToast("")} />}</div></ScreenState>;
}

function NotFound({ roleSlug }: { roleSlug?: string }) {
  return <div className="admin-screen"><div className="admin-not-found"><Gauge /><h2>Admin screen not found</h2><p>This route is not part of the approved platform administration inventory.</p><Link className="admin-button admin-button--primary admin-button--normal" href={href("/platform-admin", roleSlug)}>Return to overview</Link></div></div>;
}

export function AdminScreens(props: ScreenProps) {
  const [root, detail] = props.route.split("/");
  if (!props.route) return <Overview {...props} />;
  if (root === "companies") return detail ? <CompanyDetail {...props} slug={detail} /> : <Companies {...props} />;
  if (root === "users") return detail ? <UserDetail {...props} slug={detail} /> : <Users {...props} />;
  if (props.route === "access/roles") return <AdminRoles {...props} />;
  if (root === "talent-review") return <TalentReview {...props} detailSlug={detail} />;
  if (root === "jobs") return <Jobs {...props} />;
  if (["applications", "placements", "replacements"].includes(root)) return <Hiring {...props} />;
  if (root === "support") return <Support {...props} detailSlug={detail} />;
  if (root === "payments") return <Payments {...props} />;
  if (root === "communications") return <Communications {...props} />;
  if (root === "content") return <ContentConfig {...props} />;
  if (root === "analytics") return <Analytics {...props} />;
  if (root === "exports") return <Exports {...props} />;
  if (root === "audit") return <Audit {...props} />;
  if (root === "system") return <SystemOperations {...props} />;
  if (root === "account") return <Account {...props} />;
  return <NotFound roleSlug={props.roleSlug} />;
}
